// 4. SSL certificate manual renew
function illustrationSslCertificateManualRenewWithCommandLine() {
  return `
    <rect x="0" y="0" width="1080" height="700" fill="none"/>
    <!-- Lock/shield icon -->
    <g transform="translate(540, 220)">
      <path d="M0,-80 L60,-55 L60,20 Q60,70 0,90 Q-60,70 -60,20 L-60,-55 Z" fill="none" stroke="#00e5ff" stroke-width="2.5"/>
      <rect x="-20" y="-15" width="40" height="35" rx="4" fill="none" stroke="#ffe66d" stroke-width="2"/>
      <path d="M-14,-15 L-14,-30 Q-14,-50 0,-50 Q14,-50 14,-30 L14,-15" fill="none" stroke="#ffe66d" stroke-width="2"/>
      <circle cx="0" cy="5" r="5" fill="#ffe66d" opacity="0.8"/>
    </g>
    <!-- Certificate badge -->
    <circle cx="540" y="220" r="3" fill="#4ecdc4"/>
    <!-- Terminal window -->
    <rect x="240" y="380" width="600" height="200" rx="10" fill="#111" stroke="#333" stroke-width="1.5"/>
    <circle cx="268" cy="400" r="6" fill="#ff6b6b" opacity="0.7"/>
    <circle cx="288" cy="400" r="6" fill="#ffe66d" opacity="0.7"/>
    <circle cx="308" cy="400" r="6" fill="#4ecdc4" opacity="0.7"/>
    <text x="270" y="440" font-family="monospace" font-size="13" fill="#4ecdc4" opacity="0.8">$ sudo synow3tool --ssl-renew</text>
    <text x="270" y="462" font-family="monospace" font-size="13" fill="#888" opacity="0.6">Renewing certificate...</text>
    <text x="270" y="484" font-family="monospace" font-size="13" fill="#a8e6cf" opacity="0.7">Certificate renewed successfully</text>
    <text x="270" y="510" font-family="monospace" font-size="13" fill="#00e5ff" opacity="0.6">Valid: 2024-01-01 ~ 2025-01-01</text>
    <!-- Renewal arrow -->
    <g transform="translate(780, 220)">
      <path d="M20,0 A25,25 0 1,1 0,-20" fill="none" stroke="#a8e6cf" stroke-width="2"/>
      <polygon points="-5,-25 0,-15 5,-25" fill="#a8e6cf"/>
    </g>
    <text x="540" y="640" text-anchor="middle" font-family="monospace" font-size="13" fill="#555">SSL CERTIFICATE RENEWAL</text>
  `;
}

